mapper.select:
    	/* saleson.shop.slave.SlaveGiveStateMapper.getGiveStateSum */
        SELECT
		    IFNULL(SUM(GC.CNTR_AMT), 0) AS CNTR_AMT
		    , IFNULL(COUNT(DISTINCT(USER_ID)), 0) AS GIVE_PERSONS
		    , IFNULL(SUM(GC.CNTR_POINT), 0) AS CNTR_POINT
		    , (
		    	SELECT IFNULL(SUM(CNTR_USE_POINT), 0)
		    	FROM G_CNTR_USE_POINT
		    	WHERE use_se_code ='1'

					AND cntr_locgov_code = #{shLocgovCode}


					AND year(point_use_de) = #{shCntrYear}

		      ) AS CNTR_USE_POINT
		FROM G_CNTR GC
		WHERE 1=1
		AND GC.DELETE_AT = 'N'
		and GC.cntr_sttus_code = '200'
        and GC.sttemnt_pay_de is not NULL

		AND year(GC.CNTR_DE) = #{shCntrYear}


		AND GC.CNTR_LOCGOV_CODE = #{shLocgovCode}

/* saleson.shop.slave.SlaveGiveStateMapper.getGiveStateListCount */ SELECT COUNT(*) FROM ( SELECT YEAR(gc.cntr_de) as cntr_year , gc.cntr_locgov_code , SUM(gc.cntr_amt) as cntr_amt , COUNT(DISTINCT(user_id)) as give_persons , SUM(gc.cntr_point) as cntr_point , COUNT(cntr_sn) as give_cnt from g_cntr gc WHERE 1=1 AND gc.cntr_sttus_code = '200'
AND gc.cntr_locgov_code = #{shLocgovCode}
AND YEAR(gc.cntr_de) = #{shCntrYear}
GROUP BY YEAR(gc.cntr_de), gc.cntr_locgov_code ) gc

/* saleson.shop.slave.SlaveGiveStateMapper.getGiveStateList */ SELECT gc.cntr_year , gc.cntr_amt , gc.give_persons , gc.cntr_point , gc.give_cnt , gl.upper_locgov_code , gl.upper_locgov_nm , gl.locgov_code , gl.locgov_nm , ( SELECT IFNULL(SUM(cntr_use_point), 0) FROM g_cntr_use_point a WHERE use_se_code ='1' AND a.cntr_locgov_code = gc.cntr_locgov_code
AND a.cntr_locgov_code = #{shLocgovCode}
AND year(point_use_de) = #{shCntrYear}
) AS cntr_use_point FROM ( SELECT YEAR(gc.cntr_de) as cntr_year , gc.cntr_locgov_code , SUM(gc.cntr_amt) as cntr_amt , COUNT(DISTINCT(user_id)) as give_persons , SUM(gc.cntr_point) as cntr_point , COUNT(cntr_sn) as give_cnt from g_cntr gc WHERE 1=1 AND gc.cntr_sttus_code = '200'
AND gc.cntr_locgov_code = #{shLocgovCode}
AND YEAR(gc.cntr_de) = #{shCntrYear}
GROUP BY YEAR(gc.cntr_de), gc.cntr_locgov_code
) gc INNER JOIN g_locgov gl on gc.cntr_locgov_code = gl.locgov_code ORDER BY gc.cntr_year DESC, gl.upper_locgov_code, gl.locgov_code

/* saleson.shop.slave.SlaveGiveStateMapper.getGiveStateDetailSum */ SELECT IFNULL(SUM(CNTR_AMT), 0) AS CNTR_AMT , COUNT(DISTINCT(GC.USER_ID)) AS GIVE_PERSONS , IFNULL(SUM(CNTR_POINT), 0) AS CNTR_POINT FROM G_CNTR GC LEFT JOIN OP_COMMON_CODE CC on CC.ID = GC.LINK_INSTT_CD AND CC.CODE_TYPE = 'LINK_INSTT_CD' , OP_USER OU , OP_USER_DETAIL OUD WHERE 1=1 AND GC.USER_ID = OU.USER_ID AND GC.USER_ID = OUD.USER_ID AND GC.DELETE_AT = 'N' and GC.cntr_sttus_code = '200' and GC.sttemnt_pay_de is not NULL
AND CNTR_LOCGOV_CODE = #{shLocgovCode}
AND year(GC.CNTR_DE) = #{shCntrYear}
AND CNTR_DE BETWEEN #{shCntrDeStart} AND #{shCntrDeEnd}
AND CNTR_PATH_CODE = '100'
AND CNTR_PATH_CODE IN ('200', '300')
AND OU.LOGIN_ID = #{shText}
AND OU.USER_NAME = #{shText}
AND GC.ELCTRN_PAY_NO = #{shText}
AND (SELECT DSGN_DNTN_BIZ_TTL FROM G_DSGN_DNTN_BIZ_MNG A WHERE A.DSGN_DNTN_BIZ_ID = GC.DSGN_DNTN_BIZ_ID) LIKE CONCAT('%',#{shText},'%')
AND GC.DSGN_DNTN_BIZ_ID = 0
AND GC.DSGN_DNTN_BIZ_ID IS NOT NULL AND GC.DSGN_DNTN_BIZ_ID != ''
AND GC.LINK_INSTT_CD IS NULL
AND GC.LINK_INSTT_CD IS NOT NULL
AND GC.LINK_INSTT_CD = #{shLinkInsttCd}
AND ( GC.RTNPSNT_REQST_CODE = '100' AND GC.CNTR_POINT <> (SELECT IFNULL(SUM(GCP.CNTR_USE_POINT),0) FROM G_CNTR_USE_POINT GCP WHERE GCP.CNTR_SN = GC.CNTR_SN AND GCP.USE_SE_CODE ='1' ))
AND (GC.RTNPSNT_REQST_CODE ='300' OR GC.CNTR_POINT = (SELECT IFNULL(SUM(GCP.CNTR_USE_POINT),0) FROM G_CNTR_USE_POINT GCP WHERE GCP.CNTR_SN = GC.CNTR_SN AND GCP.USE_SE_CODE ='1' ))
AND GC.CNTR_AMT >= #{shCntrAmtStart}
AND GC.CNTR_AMT <= #{shCntrAmtEnd}
AND (OUD.RECEIVE_PBANC is null OR OUD.RECEIVE_PBANC = '1')
AND OUD.RECEIVE_PBANC = '0'

/* saleson.shop.slave.SlaveGiveStateMapper.getGiveStateDetailListCount */ SELECT COUNT(*) FROM ( SELECT CNTR_DE , ELCTRN_PAY_NO , OU.USER_NAME , CNTR_AMT , CNTR_POINT , CNTR_PATH_CODE , (SELECT LABEL FROM OP_COMMON_CODE OCC WHERE ID = GC.CNTR_PATH_CODE AND CODE_TYPE = 'CNTR_PATH' AND USE_YN = 'Y') AS CNTR_PATH_NAME , LINK_INSTT_CD FROM G_CNTR GC LEFT JOIN OP_COMMON_CODE CC on CC.ID = GC.LINK_INSTT_CD AND CC.CODE_TYPE = 'LINK_INSTT_CD' , OP_USER OU , OP_USER_DETAIL OUD WHERE 1=1 AND GC.USER_ID = OU.USER_ID AND GC.USER_ID = OUD.USER_ID AND GC.DELETE_AT = 'N' and GC.cntr_sttus_code = '200' and GC.sttemnt_pay_de is not NULL
AND CNTR_LOCGOV_CODE = #{shLocgovCode}
AND year(GC.CNTR_DE) = #{shCntrYear}
AND CNTR_DE BETWEEN #{shCntrDeStart} AND #{shCntrDeEnd}
AND CNTR_PATH_CODE = '100'
AND CNTR_PATH_CODE IN ('200', '300')
AND OU.LOGIN_ID = #{shText}
AND OU.USER_NAME = #{shText}
AND GC.ELCTRN_PAY_NO = #{shText}
AND (SELECT DSGN_DNTN_BIZ_TTL FROM G_DSGN_DNTN_BIZ_MNG A WHERE A.DSGN_DNTN_BIZ_ID = GC.DSGN_DNTN_BIZ_ID) LIKE CONCAT('%',#{shText},'%')
AND GC.DSGN_DNTN_BIZ_ID = 0
AND GC.DSGN_DNTN_BIZ_ID IS NOT NULL AND GC.DSGN_DNTN_BIZ_ID != ''
AND GC.LINK_INSTT_CD IS NULL
AND GC.LINK_INSTT_CD IS NOT NULL
AND GC.LINK_INSTT_CD = #{shLinkInsttCd}
AND ( GC.RTNPSNT_REQST_CODE = '100' AND GC.CNTR_POINT <> (SELECT IFNULL(SUM(GCP.CNTR_USE_POINT),0) FROM G_CNTR_USE_POINT GCP WHERE GCP.CNTR_SN = GC.CNTR_SN AND GCP.USE_SE_CODE ='1' ))
AND (GC.RTNPSNT_REQST_CODE ='300' OR GC.CNTR_POINT = ( SELECT IFNULL(SUM(GCP.CNTR_USE_POINT),0) FROM G_CNTR_USE_POINT GCP WHERE GCP.CNTR_SN = GC.CNTR_SN AND GCP.USE_SE_CODE ='1' ))
AND GC.CNTR_AMT >= #{shCntrAmtStart}
AND GC.CNTR_AMT <= #{shCntrAmtEnd}
AND (OUD.RECEIVE_PBANC is null OR OUD.RECEIVE_PBANC = '1')
AND OUD.RECEIVE_PBANC = '0'
) A

/* saleson.shop.slave.SlaveGiveStateMapper.getGiveStateDetailList */ SELECT A.CNTR_SN , A.CNTR_DE , A.STTEMNT_PAY_DE , A.USER_NAME USER_NAME , A.LOGIN_ID LOGIN_ID , A.CNTR_AMT , A.CNTR_POINT , A.CNTR_POINT - A.CNTR_USE_POINT as CNTR_BLCE_POINT , A.CNTR_PATH_CODE , (SELECT LABEL FROM OP_COMMON_CODE OCC WHERE ID = A.CNTR_PATH_CODE AND CODE_TYPE = 'CNTR_PATH' AND USE_YN = 'Y') AS CNTR_PATH_NAME , A.RTNPSNT_REQST_CODE , A.ELCTRN_PAY_NO , A.CNTR_REQMNG_CODE , (SELECT LABEL FROM OP_COMMON_CODE OCC WHERE ID = A.CNTR_REQMNG_CODE AND CODE_TYPE = 'CNTR_REQMNG' AND USE_YN = 'Y') AS CNTR_REQMNG_CODE_NAME , A.REQ_STATUS_CODE , (SELECT LABEL FROM OP_COMMON_CODE OCC WHERE ID = A.REQ_STATUS_CODE AND CODE_TYPE = 'REQ_STATUS' AND USE_YN = 'Y') AS REQ_STATUS_CODE_NAME , A.FRST_REGIST_PNTTM , A.APPR_DT , (CASE WHEN A.NTS_CNT = 0 THEN '-' ELSE '내역' END) AS NTS_STTUS_MSSAGE , (SELECT UPPER_LOCGOV_NM||' '||LOCGOV_NM FROM G_LOCGOV GL WHERE A.PSITN_LOCGOV_CODE = GL.LOCGOV_CODE) AS PSITN_LOCGOV_NAME , CASE WHEN A.BIRTHDAY = '' THEN '-' WHEN (A.BIRTHDAY REGEXP '^[0-9]{4}(0[1-9]|1[0-2])(0[1-9]|[12][0-9]|3[01])$') = 0 THEN '-' ELSE DATE_FORMAT(A.BIRTHDAY, '%Y-%m-%d') END AS BIRTHDAY , A.PHONE_NUMBER AS PHONE_NUMBER , A.RECEIVE_PBANC , CASE WHEN A.RECEIVE_PBANC = '0' THEN '동의' ELSE '미동의' END AS pbancName , A.PRJ_ID , A.PRJ_SUBJECT , IFNULL((SELECT COUNT(B.ELCTRN_PAY_NO) FROM G_CNTR_TAX_LOG B WHERE B.ELCTRN_PAY_NO = A.ELCTRN_PAY_NO), 0) AS NTS_CNT , A.DETAIL FROM ( SELECT GC.CNTR_SN , DATE_FORMAT(GC.FRST_REGIST_PNTTM,'%Y-%m-%d %H:%i:%s') AS CNTR_DE , DATE_FORMAT(GC.STTEMNT_PAY_DE,'%Y-%m-%d') AS STTEMNT_PAY_DE , OU.USER_NAME , OU.LOGIN_ID , GC.CNTR_AMT , GC.CNTR_POINT , ( SELECT IFNULL(SUM(GCP.CNTR_USE_POINT),0) FROM G_CNTR_USE_POINT GCP WHERE GCP.CNTR_SN = GC.CNTR_SN AND GCP.USE_SE_CODE ='1' ) as CNTR_USE_POINT , GC.CNTR_PATH_CODE , GC.RTNPSNT_REQST_CODE , GC.ELCTRN_PAY_NO , GCR.CNTR_REQMNG_CODE , GCR.REQ_STATUS_CODE , DATE_FORMAT(GCR.FRST_REGIST_PNTTM,'%Y-%m-%d %H:%i:%s') AS FRST_REGIST_PNTTM , DATE_FORMAT(GCR.APPR_DT,'%Y-%m-%d %H:%i:%s') AS APPR_DT , IFNULL((SELECT COUNT(ELCTRN_PAY_NO) FROM G_CNTR_TAX_LOG WHERE NTS_RES_CODE = '200' AND ELCTRN_PAY_NO = GC.ELCTRN_PAY_NO), 0) AS NTS_CNT , GC.PSITN_LOCGOV_CODE , OUD.BIRTHDAY , OUD.PHONE_NUMBER , OUD.RECEIVE_PBANC , IFNULL(GC.DSGN_DNTN_BIZ_ID, 0) AS PRJ_ID , IFNULL(DPM.DSGN_DNTN_BIZ_TTL, '자치단체기부') AS PRJ_SUBJECT , CC.DETAIL FROM G_CNTR GC LEFT JOIN ( SELECT A.CNTR_SN, A.CNTR_REQMNG_CODE, A.REQ_STATUS_CODE, A.FRST_REGIST_PNTTM, A.APPR_DT FROM G_CNTR_REQMNG A WHERE A.REQ_STATUS_CODE != '200' AND A.FRST_REGIST_PNTTM = (SELECT MAX(B.FRST_REGIST_PNTTM) FROM G_CNTR_REQMNG B WHERE B.CNTR_SN = A.CNTR_SN) ) GCR ON GC.CNTR_SN = GCR.CNTR_SN LEFT JOIN G_DSGN_DNTN_BIZ_MNG DPM ON DPM.DSGN_DNTN_BIZ_ID = GC.DSGN_DNTN_BIZ_ID LEFT JOIN OP_COMMON_CODE CC on CC.ID = GC.LINK_INSTT_CD AND CC.CODE_TYPE = 'LINK_INSTT_CD' , OP_USER OU , OP_USER_DETAIL OUD WHERE 1=1 AND GC.USER_ID = OU.USER_ID AND GC.USER_ID = OUD.USER_ID AND GC.DELETE_AT = 'N' AND GC.CNTR_STTUS_CODE = '200' AND GC.STTEMNT_PAY_DE IS NOT NULL
AND CNTR_LOCGOV_CODE = #{shLocgovCode}
AND YEAR(GC.CNTR_DE) = #{shCntrYear}
AND CNTR_DE BETWEEN #{shCntrDeStart} AND #{shCntrDeEnd}
AND CNTR_PATH_CODE = '100'
AND CNTR_PATH_CODE IN ('200', '300')
AND OU.LOGIN_ID = #{shText}
AND OU.USER_NAME = #{shText}
AND GC.ELCTRN_PAY_NO = #{shText}
AND DPM.DSGN_DNTN_BIZ_TTL LIKE CONCAT('%',#{shText},'%')
AND GC.DSGN_DNTN_BIZ_ID = 0
AND GC.DSGN_DNTN_BIZ_ID IS NOT NULL AND GC.DSGN_DNTN_BIZ_ID != ''
AND GC.LINK_INSTT_CD IS NULL
AND GC.LINK_INSTT_CD IS NOT NULL
AND GC.LINK_INSTT_CD = #{shLinkInsttCd}
AND ( GC.RTNPSNT_REQST_CODE = '100' AND GC.CNTR_POINT <> (SELECT IFNULL(SUM(GCP.CNTR_USE_POINT),0) FROM G_CNTR_USE_POINT GCP WHERE GCP.CNTR_SN = GC.CNTR_SN AND GCP.USE_SE_CODE ='1' ))
AND (GC.RTNPSNT_REQST_CODE ='300' OR GC.CNTR_POINT = ( SELECT IFNULL(SUM(GCP.CNTR_USE_POINT),0) FROM G_CNTR_USE_POINT GCP WHERE GCP.CNTR_SN = GC.CNTR_SN AND GCP.USE_SE_CODE ='1' ))
AND GC.CNTR_AMT >= #{shCntrAmtStart}
AND GC.CNTR_AMT <= #{shCntrAmtEnd}
AND (OUD.RECEIVE_PBANC is null OR OUD.RECEIVE_PBANC = '1')
AND OUD.RECEIVE_PBANC = '0'
) A ORDER BY A.CNTR_DE DESC, A.FRST_REGIST_PNTTM DESC

		/* saleson.shop.slave.SlaveGiveStateMapper.getGiveStateDetailListCountTest */
	    SELECT COUNT(*)
        FROM
        (
		    SELECT
		        CNTR_DE
	                , OU.USER_NAME
	                , CNTR_AMT
	                , CNTR_POINT
	                , CNTR_PATH_CODE
	                , (SELECT LABEL FROM OP_COMMON_CODE OCC WHERE ID = GC.CNTR_PATH_CODE AND CODE_TYPE = 'CNTR_PATH' AND USE_YN = 'Y') AS CNTR_PATH_NAME
	                , (SELECT LABEL FROM OP_COMMON_CODE OCC WHERE ID = GC.CNTR_PATH_CODE AND CODE_TYPE = 'LINK_INSTT_CD' AND USE_YN = 'Y') AS LINK_INSTT_CD_DETAIL
		    FROM G_CNTR GC
		    LEFT JOIN OP_COMMON_CODE CC on CC.ID = GC.LINK_INSTT_CD AND CC.CODE_TYPE = 'LINK_INSTT_CD'
		    , OP_USER OU
		    WHERE 1=1
		    AND GC.USER_ID = OU.USER_ID

		    AND CNTR_LOCGOV_CODE = #{shLocgovCode}


		    AND year(GC.CNTR_DE) = #{shCntrYear}


		    AND CNTR_DE BETWEEN #{shCntrDeStart} AND #{shCntrDeEnd}



            AND STTEMNT_PAY_DE BETWEEN #{shSttemntPayDeStart} AND #{shSttemntPayDeEnd}




		    AND CNTR_PATH_CODE = '100' 


		    AND CNTR_PATH_CODE IN ('200', '300') 


            AND delete_at = #{shDeleteAt}




					AND OU.USER_NAME = #{shText}


					AND OU.LOGIN_ID = #{shText}


					AND GC.ELCTRN_PAY_NO = #{shText}



					AND (SELECT DSGN_DNTN_BIZ_TTL FROM G_DSGN_DNTN_BIZ_MNG A WHERE A.DSGN_DNTN_BIZ_ID = GC.DSGN_DNTN_BIZ_ID) LIKE CONCAT('%',#{shText},'%')







						AND GC.DSGN_DNTN_BIZ_ID = 0



						AND GC.DSGN_DNTN_BIZ_ID IS NOT NULL AND GC.DSGN_DNTN_BIZ_ID != ''






						AND GC.LINK_INSTT_CD IS NULL



							AND GC.LINK_INSTT_CD IS NOT NULL


							AND GC.LINK_INSTT_CD = #{shLinkInsttCd}







						AND GC.cntr_sttus_code = '100'


						AND GC.cntr_sttus_code = '200'


						AND GC.cntr_sttus_code = '300'




            AND GC.CNTR_AMT >= #{shCntrAmtStart}


            AND GC.CNTR_AMT <= #{shCntrAmtEnd}

        )

/* saleson.shop.slave.SlaveGiveStateMapper.getGiveStateDetailListTest */ select cntr_sn, cntr_de, A.user_id, cntr_amt, cntr_point, (cntr_point - cntr_use_point) as cntr_blce_point, point_end_de, sttemnt_pay_de, pay_valid_de, cntrbtr_opinion_cn, setle_mth_code, cntr_use_purps_code, elctrn_pay_no, seoul_trget_at, rcept_bank_code, rcept_bank_nm, rtnpsnt_reqst_at, info_agre_at, frst_register_id, last_updusr_id
, (CASE WHEN A.NTS_CNT = 0 THEN '-' ELSE '내역' END) AS NTS_STTUS_MSSAGE ,(select concat(upper_locgov_nm, ' ', locgov_nm) from g_locgov where locgov_code=A.psitn_locgov_code) as psitn_locgov_code ,(select concat(upper_locgov_nm, ' ', locgov_nm) from g_locgov where locgov_code=A.cntr_locgov_code) as cntr_locgov_code , (A.user_name) user_name , (A.login_id) login_id , (rcepter_nm) rcepter_nm ,(select label from op_common_code where id = cntr_path_code and code_type = 'CNTR_PATH' and use_yn = 'Y') as cntr_path_code ,(select label from op_common_code where id = cntr_sttus_code and code_type = 'CNTR_STTUS' and use_yn = 'Y') as cntr_sttus_code ,(select detail from op_common_code where id = rtnpsnt_reqst_code and code_type = 'RTNPSNT_REQST' and use_yn = 'Y') as rtnpsnt_reqst_code ,to_char(frst_regist_pnttm,'YYYY-MM-DD hh24:mi:ss') as frst_regist_pnttm ,to_char(last_updt_pnttm,'YYYY-MM-DD hh24:mi:ss') as last_updt_pnttm , ifnull(prj_id, 0) as prj_id , ifnull(prj_subject, '자치단체기부') as prj_subject , detail from ( SELECT cntr_sn, cntr_de, GC.user_id, cntr_amt, cntr_point, (SELECT IFNULL(SUM(cntr_use_point),0) FROM g_cntr_use_point a WHERE a.cntr_sn = GC.cntr_sn) AS cntr_use_point, point_end_de, sttemnt_pay_de, pay_valid_de, cntrbtr_opinion_cn, setle_mth_code, cntr_use_purps_code, elctrn_pay_no, seoul_trget_at, rcept_bank_code, rcept_bank_nm, rtnpsnt_reqst_at, info_agre_at, frst_register_id, last_updusr_id
, IFNULL((SELECT COUNT(ELCTRN_PAY_NO) FROM G_CNTR_TAX_LOG WHERE ELCTRN_PAY_NO = GC.ELCTRN_PAY_NO), 0) AS NTS_CNT ,psitn_locgov_code,cntr_locgov_code ,OU.user_name ,OU.login_id ,rcepter_nm ,cntr_path_code ,cntr_sttus_code ,rtnpsnt_reqst_code ,frst_regist_pnttm ,last_updt_pnttm ,DSGN_DNTN_BIZ_ID AS prj_id ,(SELECT DSGN_DNTN_BIZ_TTL FROM G_DSGN_DNTN_BIZ_MNG a WHERE a.DSGN_DNTN_BIZ_ID = GC.DSGN_DNTN_BIZ_ID) AS prj_subject ,CC.detail FROM G_CNTR GC LEFT JOIN OP_COMMON_CODE CC on CC.ID = GC.LINK_INSTT_CD AND CC.CODE_TYPE = 'LINK_INSTT_CD' , OP_USER OU WHERE 1=1 AND GC.USER_ID = OU.USER_ID
AND CNTR_LOCGOV_CODE = #{shLocgovCode}
AND year(GC.CNTR_DE) = #{shCntrYear}
AND CNTR_DE BETWEEN #{shCntrDeStart} AND #{shCntrDeEnd}
AND STTEMNT_PAY_DE BETWEEN #{shSttemntPayDeStart} AND #{shSttemntPayDeEnd}
AND CNTR_PATH_CODE = '100'
AND CNTR_PATH_CODE IN ('200', '300')
AND USER_NAME = #{shUserName}
AND USER_NAME = #{shText}
AND OU.LOGIN_ID = #{shText}
AND GC.ELCTRN_PAY_NO = #{shText}
AND (SELECT DSGN_DNTN_BIZ_TTL FROM G_DSGN_DNTN_BIZ_MNG A WHERE A.DSGN_DNTN_BIZ_ID = GC.DSGN_DNTN_BIZ_ID) LIKE CONCAT('%',#{shText},'%')
AND GC.DSGN_DNTN_BIZ_ID = 0
AND GC.DSGN_DNTN_BIZ_ID IS NOT NULL AND GC.DSGN_DNTN_BIZ_ID != ''
AND GC.LINK_INSTT_CD IS NULL
AND GC.LINK_INSTT_CD IS NOT NULL
AND GC.LINK_INSTT_CD = #{shLinkInsttCd}
AND GC.cntr_sttus_code = '100'
AND GC.cntr_sttus_code = '200'
AND GC.cntr_sttus_code = '300'
AND GC.CNTR_AMT >= #{shCntrAmtStart}
AND GC.CNTR_AMT <= #{shCntrAmtEnd}
ORDER BY cntr_de desc, frst_regist_pnttm desc
) A


	    	/* saleson.shop.slave.SlaveGiveStateMapper.getGiveStateDetailListCountCntr */
		    SELECT
				count(*) as cnt
		    FROM G_CNTR GC, OP_USER OU
            WHERE 1=1
            AND GC.USER_ID = OU.USER_ID

            AND cntr_sn = #{shCntrSn}


            AND CNTR_DE BETWEEN #{shCntrDeStart} AND #{shCntrDeEnd}


            AND USER_NAME = #{shUserName}


            AND OU.login_id = #{shLoginId}


            AND CNTR_LOCGOV_CODE = #{shLocgovCode}


            AND sttemnt_pay_de = #{shSttemntPayDe}



		    AND CNTR_PATH_CODE = '100' 


		    AND CNTR_PATH_CODE IN ('200', '300') 


            AND cntr_sttus_code = #{shCntrSttusCode}


            AND elctrn_pay_no = #{shElctrnPayNo}

            ORDER BY GC.cntr_sn DESC

/* saleson.shop.slave.SlaveGiveStateMapper.getGiveStateDetailListCntr */ SELECT A.cntr_sn , A.cntr_de , A.user_id , A.USER_NAME USER_NAME , A.LOGIN_ID LOGIN_ID , A.psitn_locgov_code , A.cntr_locgov_code , (select concat(upper_locgov_nm, ' ', locgov_nm) from g_locgov where locgov_code=A.psitn_locgov_code) as psitn_locgov_code_name , (select concat(upper_locgov_nm, ' ', locgov_nm) from g_locgov where locgov_code=A.cntr_locgov_code) as cntr_locgov_code_name , A.cntr_amt , A.cntr_point , A.cntr_point - A.cntr_use_point AS cntr_blce_point , A.point_end_de , A.sttemnt_pay_de , A.pay_valid_de , A.cntr_path_code , A.cntr_sttus_code , A.cntrbtr_opinion_cn , A.setle_mth_code , A.cntr_use_purps_code , A.elctrn_pay_no , A.seoul_trget_at , A.rcept_bank_code , (SELECT LABEL FROM OP_COMMON_CODE OCC WHERE ID = A.RCEPT_BANK_CODE AND CODE_TYPE = 'OFF_BANK_LIST' AND USE_YN = 'Y') AS RCEPT_BANK_CODE_NM , A.rcept_bank_nm , A.rcepter_nm rcepter_nm , A.rtnpsnt_reqst_code , A.rtnpsnt_reqst_at , A.info_agre_at , A.frst_register_id , A.frst_regist_pnttm , A.last_updusr_id , A.last_updt_pnttm , A.delete_at , A.nts_sttus_mssage FROM ( SELECT GC.cntr_sn , GC.cntr_de , GC.user_id , OU.USER_NAME , OU.LOGIN_ID , GC.psitn_locgov_code , GC.cntr_locgov_code , GC.cntr_amt , GC.cntr_point , (SELECT IFNULL(SUM(cntr_use_point),0) FROM g_cntr_use_point a WHERE a.cntr_sn = GC.cntr_sn) AS cntr_use_point , GC.point_end_de , GC.sttemnt_pay_de , GC.pay_valid_de , GC.cntr_path_code , GC.cntr_sttus_code , GC.cntrbtr_opinion_cn , GC.setle_mth_code , GC.cntr_use_purps_code , GC.elctrn_pay_no , GC.seoul_trget_at , GC.rcept_bank_code , GC.rcept_bank_nm , GC.rcepter_nm , GC.rtnpsnt_reqst_code , GC.rtnpsnt_reqst_at , GC.info_agre_at , GC.frst_register_id , GC.frst_regist_pnttm , GC.last_updusr_id , GC.last_updt_pnttm , GC.delete_at , GC.nts_sttus_mssage FROM G_CNTR GC, OP_USER OU WHERE 1=1 AND GC.USER_ID = OU.USER_ID
AND cntr_sn = #{shCntrSn}
AND CNTR_DE BETWEEN #{shCntrDeStart} AND #{shCntrDeEnd}
AND USER_NAME = #{shUserName}
AND OU.login_id = #{shLoginId}
AND CNTR_LOCGOV_CODE = #{shLocgovCode}
AND sttemnt_pay_de = #{shSttemntPayDe}
AND CNTR_PATH_CODE = #{shCntrPathCode} -- 100: 온라인, 200:오프라인
AND cntr_sttus_code = #{shCntrSttusCode}
AND elctrn_pay_no = #{shElctrnPayNo}
AND delete_at = #{shDeleteAt}
) A ORDER BY GC.cntr_sn desc

/* saleson.shop.slave.SlaveGiveStateMapper.getGiveReqmngCount */ SELECT COUNT(*) as cnt FROM G_CNTR_REQMNG GCR, OP_MANAGER OM WHERE 1=1 AND GCR.FRST_REGISTER_ID = OM.USER_ID
AND GCR.LOCGOV_CODE = #{shLocgovCode}
AND TO_CHAR(GCR.FRST_REGIST_PNTTM,'YYYYMMDD') BETWEEN #{shFrstRegistPnttmStart} AND #{shFrstRegistPnttmEnd}
AND GCR.CNTR_REQMNG_CODE = #{shCntrReqmngCode} -- 100: 과오납, 200: 포인트생성
AND GCR.REQ_STATUS_CODE = #{shReqStatusCode} -- 100:요청 200:취소 999:승인
AND GCR.cntr_sn = (select cntr_sn from g_cntr where elctrn_pay_no = #{shElctrnPayNo})
AND GCR.USE_YN = 'Y'

/* saleson.shop.slave.SlaveGiveStateMapper.getGiveReqmngList */ SELECT t.REQ_ID , t.LOGIN_ID AS LOGIN_ID , t.USER_NAME AS USER_NAME , u.USER_ID AS user_id , t.LOCGOV_CODE , (l.upper_locgov_nm || '' || l.locgov_nm) as LOCGOV_CODE_NAME , t.STTEMNT_PAY_DE , t.CNTR_AMT , t.CNTR_REQMNG_CODE , cc_reqmng.label as CNTR_REQMNG_CODE_NAME , t.DISCRIPTION , m1.login_id AS FRST_REGISTER_ID , t.FRST_REGIST_PNTTM , m2.login_id AS LAST_UPDUSR_ID , t.LAST_UPDT_PNTTM , DATE_FORMAT(t.APPR_DT,'%Y-%m-%d %H:%i:%s') AS APPR_DT , DATE_FORMAT(t.CANCLE_DT,'%Y-%m-%d %H:%i:%s') AS CANCLE_DT , t.REQ_STATUS_CODE , cc_status.label as REQ_STATUS_CODE_NAME , t.CNTR_SN , GC.ELCTRN_PAY_NO , cc_link.DETAIL , GC.LINK_INSTT_CD FROM ( SELECT GCR.REQ_ID , GCR.LOGIN_ID , GCR.USER_NAME , GCR.LOCGOV_CODE , GCR.STTEMNT_PAY_DE , GCR.CNTR_AMT , GCR.CNTR_REQMNG_CODE , GCR.DISCRIPTION , GCR.FRST_REGISTER_ID , GCR.FRST_REGIST_PNTTM , GCR.LAST_UPDUSR_ID , GCR.LAST_UPDT_PNTTM , GCR.APPR_DT , GCR.CANCLE_DT , GCR.REQ_STATUS_CODE , GCR.CNTR_SN FROM G_CNTR_REQMNG GCR WHERE 1=1
AND GCR.LOCGOV_CODE = #{shLocgovCode}
AND TO_CHAR(GCR.FRST_REGIST_PNTTM,'YYYYMMDD') BETWEEN #{shFrstRegistPnttmStart} AND #{shFrstRegistPnttmEnd}
AND GCR.CNTR_REQMNG_CODE = #{shCntrReqmngCode}
AND GCR.REQ_STATUS_CODE = #{shReqStatusCode}
AND GCR.cntr_sn = (select cntr_sn from g_cntr where elctrn_pay_no = #{shElctrnPayNo})
AND GCR.USE_YN = 'Y' ORDER BY (CASE WHEN GCR.LAST_UPDT_PNTTM IS NULL THEN 1 ELSE 2 END ), GCR.REQ_ID DESC
) t INNER JOIN G_CNTR GC ON t.CNTR_SN = GC.CNTR_SN
LEFT JOIN OP_USER u ON u.LOGIN_ID = t.LOGIN_ID
LEFT JOIN G_LOCGOV l ON l.LOCGOV_CODE = t.LOCGOV_CODE
LEFT JOIN OP_COMMON_CODE cc_reqmng ON cc_reqmng.id = t.CNTR_REQMNG_CODE AND cc_reqmng.CODE_TYPE = 'CNTR_REQMNG' AND cc_reqmng.USE_YN = 'Y'
LEFT JOIN OP_COMMON_CODE cc_status ON cc_reqmng.id = t.CNTR_REQMNG_CODE AND cc_reqmng.CODE_TYPE = 'REQ_STATUS' AND cc_reqmng.USE_YN = 'Y'
LEFT JOIN OP_MANAGER m1 ON m1.USER_ID = t.FRST_REGISTER_ID
LEFT JOIN OP_MANAGER m2 ON m2.USER_ID = t.LAST_UPDUSR_ID
LEFT JOIN OP_COMMON_CODE cc_link ON cc_link.ID = GC.LINK_INSTT_CD AND cc_link.CODE_TYPE = 'LINK_INSTT_CD';
